/*
$REL-COLOR: rgb(255, 0, 0);
$FIGURE-COLOR: rgb(7, 127, 20);
$GROUND-COLOR: rgb(0, 15, 221);
$EFFECTOR-COLOR: rgb(223, 0, 204);
*/
/**
    (farb) Codes für Muster-Terminologie/Bezeichner
    im Fließtext
*/
/**
    Farbcodes in Beispielsätzen
*/
a {
  color: black;
}

a:visited {
  color: black;
}

:root {
  margin: 0;
  padding: 0;
  -webkit-box-sizing: border-box;
          box-sizing: border-box;
  --FS-BODYTEXT: 20px;
  --FF-BODYTEXT: "Libertinus";
  --FF-DISPLAY: "Fira Sans";
  --FF-TERMS: "Fira Sans";
}

html {
  scroll-behavior: smooth;
  font-size: var(--FS-BODYTEXT);
}

.wrapper {
  background-color: white;
  padding: .5rem;
  --scroll_margin: 2rem;  
  position: relative;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-align: start;
      -ms-flex-align: start;
          align-items: flex-start;
  -webkit-box-pack: center;
      -ms-flex-pack: center;
          justify-content: center;
}

.wrapper.app {
  margin-top: -50px;
  margin-left: 56px;
  /* breite des Nav-Menu */
  --scroll_margin: calc(3rem + 64px);
  /* 64px ist Höhe der App-Bar */
}

@media (max-width: 1220px) {
  .wrapper {
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-align: start;
        -ms-flex-align: start;
            align-items: flex-start;
    -webkit-box-pack: start;
        -ms-flex-pack: start;
            justify-content: flex-start;
    margin-left: 56px;
  }
  .wrapper.app {
    margin-top: 90px;
    margin-left: 56px;
    /* breite des Nav-Menu */
  }
}

/* ============================================================================ */
.vas-doc {
  background-color: white;
  color: black;
  /* todo: fluid? clamp vw */
  font-size: 1rem;
  font-family: var(--FF-BODYTEXT);
  line-height: 1.3;
  max-width: 700px;
  min-width: 500px;
  /* nur dev */
  margin: 0 1rem;
  /* in bibl, oder Familienartikeln */
}

.vas-doc ul {
  list-style: none;
  margin: 0;
  margin-bottom: 1rem;
  padding: 0rem 0rem 0rem 0rem;
}

.vas-doc li::marker {
  content: "\2013";
}

.vas-doc li {
  margin: .5rem 0rem .5rem .4rem;
  padding-left: 0.4rem;
  line-height: 1.3;
}

.by {
  font-style: italic;
  font-weight: bold;
  margin: 1rem 0rem;
}

.by .author {
  font-style: normal;
}

.sm-caps {
  font-variant: small-caps;
  letter-spacing: 0.07em;
}

.pagenav {
  border-right: 1px solid #aaa;
  margin: 1rem;
  padding: 1rem;
  /* nur dev */
  position: -webkit-sticky;
  position: sticky;
  top: 50px;
  margin-top: 6rem;
  min-width: 260px;
  max-height: 100vh;
  overflow-y: auto;
}

.pagenav ul {
  margin: 0;
  padding: 0;
}

.pagenav li::marker {
  content: none;
}

.pagenav li {
  margin: 0;
  padding: 0;
  list-style: none;
}

.pagenav li a {
  display: block;
  width: 100%;
}

.pagenav .pagenav__toc > li {
  font-family: var(--FF-DISPLAY);
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.2rem;
  padding: .2rem 0rem;
}

.pagenav .pagenav__toc > li a {
  position: relative;
  text-decoration: none;
}

.pagenav .pagenav__toc > li a::before {
  content: "\25B6";
  position: absolute;
  top: 0rem;
  left: -1rem;
  z-index: 2;
  color: black;
  opacity: 0;
  -webkit-transition: opacity 300ms;
  transition: opacity 300ms;
}

.pagenav .pagenav__toc > li a:hover {
  text-decoration: underline;
}

.pagenav .pagenav__toc > li a:hover::before {
  opacity: 1;
}

.pagenav .pagenav__toc .section {
  margin-left: 1.5rem;
  line-height: 1.1;
}

.pagenav .pagenav__toc .section a::before {
  left: -2.5rem;
}

.pagenav .pagenav__label {
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: justify;
      -ms-flex-pack: justify;
          justify-content: space-between;
  margin-top: .3rem;
  /* übernimmt optisch die Gliederung in Gruppen */
}

.pagenav .pagenav__label span:first-child {
  font-family: var(--FF-TERMS);
  font-size: .8em;
  font-weight: 500;
  color: #808080;
  font-size: .6em;
  text-align: left;
  padding-left: 3px;
  color: #d51717;
}

.pagenav .pagenav__label span:last-child {
  display: none;
  font-family: var(--FF-TERMS);
  font-size: .8em;
  font-weight: 500;
  color: #0d65c2;
  font-size: .6em;
  text-align: right;
  padding-right: 3px;
}

.pagenav .pagenav__forms {
  margin: 0.2rem 0rem 0.4rem 0.1rem;
}

.pagenav .pagenav__forms > li {
  font-size: 1rem;
  line-height: 1.2;
}

.pagenav .pagenav__forms > li a {
  position: relative;
}

.pagenav .pagenav__forms > li a::before {
  content: "\25B6";
  position: absolute;
  top: 0.1rem;
  left: -1rem;
  z-index: 2;
  color: black;
}

.wrapper.app .pagenav {
  /* 50 + app bar height (64) */
  top: 130px;
}

/* STICHWORT KOPF */
.head-lzga {
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: justify;
      -ms-flex-pack: justify;
          justify-content: space-between;
  -webkit-box-align: baseline;
      -ms-flex-align: baseline;
          align-items: baseline;
  font-family: var(--FF-DISPLAY);
  margin: 1.5rem 0rem 1rem 0rem;
  border-bottom: 1px solid #aaa;
}

.lzga {
  font-size: 2rem;
  font-weight: 500;
  letter-spacing: .6;
}

.typ-ang {
  color: #999;
  text-align: right;
  font-size: .8rem;
}

/* ===== BLOCK LEVEL ================================== */
.overview-p {
  margin: 2rem 1.5rem 2.5rem 1.5rem;
}

.overview-pattern {
  margin: 1rem 0rem 2rem 1.5rem;
}

.pattern-small {
  display: -webkit-inline-box;
  display: -ms-inline-flexbox;
  display: inline-flex;
  width: 100%;
  -webkit-box-pack: start;
      -ms-flex-pack: start;
          justify-content: start;
}

.pattern-small .pitem {
  font-family: var(--FF-TERMS);
  color: white;
  padding: 3px 0.5rem;
  font-size: .8rem;
  font-weight: 500;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: center;
      -ms-flex-pack: center;
          justify-content: center;
  -webkit-box-align: center;
      -ms-flex-align: center;
          align-items: center;
  border-radius: .3em;
  white-space: nowrap;
  height: 1.2rem;
  margin: 2px;
}

.pattern-large {
  scroll-margin-top: var(--scroll_margin);
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  margin: 0rem 0rem 1rem 0rem;
  position: relative;
  height: 4rem;
}

.pattern-large .pitem-column {
  position: relative;
  width: 5.5rem;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-orient: vertical;
  -webkit-box-direction: normal;
      -ms-flex-direction: column;
          flex-direction: column;
  -webkit-box-pack: end;
      -ms-flex-pack: end;
          justify-content: flex-end;
  margin-right: .3rem;
}

.pattern-large .pitem-column .pitem {
  font-family: var(--FF-TERMS);
  color: white;
  padding: 3px 0.5rem;
  font-size: .8rem;
  font-weight: 500;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: center;
      -ms-flex-pack: center;
          justify-content: center;
  -webkit-box-align: center;
      -ms-flex-align: center;
          align-items: center;
  border-radius: .3em;
  height: 1.9rem;
}

.pattern-large .pitem-column .pitem .ktype {
  font-size: .6em;
  padding-left: .4em;
  padding-top: 1em;
}

.pattern-large .pitem-column .head {
  line-height: 1.2;
  padding-bottom: 5px;
}

.pattern-large .pitem-column .head.rel {
  font-family: var(--FF-TERMS);
  font-size: .8em;
  font-weight: 500;
  color: #d51717;
  font-size: .9em;
  position: absolute;
  top: .3rem;
  width: 14rem;
  padding-left: 2px;
}

.pattern-large .pitem-column .head.figure {
  font-family: var(--FF-TERMS);
  font-size: .8em;
  font-weight: 500;
  color: #008702;
  font-size: .6em;
  text-align: right;
  padding-right: 2px;
}

.pattern-large .pitem-column .head.ground {
  font-family: var(--FF-TERMS);
  font-size: .8em;
  font-weight: 500;
  color: #0d65c2;
  font-size: .6em;
  text-align: right;
  padding-right: 2px;
}

.pattern-large .pitem-column .head.effector {
  font-family: var(--FF-TERMS);
  font-size: .8em;
  font-weight: 500;
  color: #be45ab;
  font-size: .6em;
  text-align: right;
  padding-right: 2px;
}

/* TODO local properties für FARBE verwenden */
.pattern-large .pitem-column .head.figure .marker {
  color: white;
  background-color: #008702;
  border-radius: 50%;
  display: -webkit-inline-box;
  display: -ms-inline-flexbox;
  display: inline-flex;
  width: .8rem;
  height: .8rem;
  -webkit-box-pack: center;
      -ms-flex-pack: center;
          justify-content: center;
  -webkit-box-align: center;
      -ms-flex-align: center;
          align-items: center;
  margin-right: 1px;
}

.pattern-large .pitem-column .head.ground .marker {
