}

/* Abschnitte und ÜBerschriften */
section h1 {
  scroll-margin-top: var(--scroll_margin);
  position: relative;
  font-family: var(--FF-DISPLAY);
  font-size: 1.5rem;
  font-weight: 500;
  line-height: 1.2rem;
  margin: 2.5rem 0 .5rem 0rem;
}

/* Abschnitts Überschriften im forms-Teil */
/*
section > h2 {
    scroll-margin-top: 2rem;

    position: relative;

    font-family: var(--FF-DISPLAY);
    font-size: 1.2rem;
    font-weight: 500;
    font-style: italic;
    line-height: 1.2rem;
    margin: 0.6rem 0 .5rem 0rem;

}
*/
h1 + .sub-sec h2 {
  margin-top: 0rem;
}

.sub-sec h2 {
  scroll-margin-top: var(--scroll_margin);
  font-family: var(--FF-DISPLAY);
  font-size: 1.1rem;
  font-weight: 500;
  margin: 1.5rem 0rem 0.1rem 0rem;
}

/* 
    wie .overview-p
    eine Section mit @class=def in XML
*/
.sub-sec.def {
  margin: 2rem 1.5rem 2.5rem 1.5rem;
}

/* Im Überblick; Prototypisch ... Beispiele*/
h4 {
  font-family: var(--FF-DISPLAY);
  letter-spacing: .1rem;
  font-weight: 500;
  font-size: .7rem;
  margin: 1rem 0rem 0rem 0rem;
}

p {
  margin: 0rem 0rem 1rem 0rem;
}

/**
 * Block von Samples
 */
.examples {
  font-size: 0.9rem;
  margin: 1rem 0rem 1rem 0.1rem;
}

.sample {
  scroll-margin-top: var(--scroll_margin);
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-align: start;
      -ms-flex-align: start;
          align-items: flex-start;
  margin-bottom: 0.8rem;
  line-height: 1.2rem;
  /* gap: 6px; Safari kann das nicht ... was ein Schrott */
}

.sample-nr {
  font-family: var(--FF-DISPLAY);
  font-size: .8em;
  font-style: normal;
  padding-top: 1px;
  margin-right: 8px;
}

.sample-pref {
  font-weight: bold;
  margin-right: 2px;
