/**
 * modifikatoren akt, med, pass möglich
 */
.form-grp::after {
  position: relative;
  display: block;
  content: "";
  width: 460px;
  margin: 2em 3em;
  border-top: 1px solid #aaa;
}

.form-grp:last-child::after {
  position: relative;
  display: block;
  content: "";
  border: none;
}

.pred-list {
  position: relative;
  overflow: hidden;
  margin-bottom: 0.6rem;
  font-size: 0.9rem;
}

.pred-list input {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0;
}

.pred-list input:checked ~ .pred-list__content {
  -ms-grid-rows: 1fr;
      grid-template-rows: 1fr;
  opacity: 1;
}

.pred-list input:checked ~ .pred-list__head {
  border-bottom-right-radius: 0px;
  border-bottom-left-radius: 0px;
}

.pred-list input:checked ~ .pred-list__head label .arrow {
  -webkit-transform: rotate(180deg);
          transform: rotate(180deg);
  -webkit-transition: -webkit-transform 0.5s ease 0s;
  transition: -webkit-transform 0.5s ease 0s;
  transition: transform 0.5s ease 0s;
  transition: transform 0.5s ease 0s, -webkit-transform 0.5s ease 0s;
}

.pred-list__head {
  position: relative;
  margin: 0px 1px 1px 1px;
  /* BUG? in FF, Border-Right sonst manchmal! unsichtbar */
  padding: 1rem 1rem 0.6rem 1rem;
  background-color: #ececec;
  border-radius: 6px;
  z-index: 2;
  /* Zeile mit 'Label'-Button */
}

.pred-list__head .pred-list__lblhead {
  font-weight: bold;
}

.pred-list__head .pred-list__lblbody {
  font-weight: normal;
  font-style: italic;
}

.pred-list__head div:nth-child(2) {
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: end;
      -ms-flex-pack: end;
          justify-content: flex-end;
}

.pred-list__head label {
  -webkit-box-sizing: border-box;
          box-sizing: border-box;
  position: relative;
  background-color: white;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: justify;
      -ms-flex-pack: justify;
          justify-content: space-between;
  -webkit-box-align: center;
      -ms-flex-align: center;
          align-items: center;
  width: 130px;
  height: 32px;
  font-family: var(--FF-DISPLAY);
  font-size: .75rem;
  font-weight: 400;
  padding: 1px .2rem 0rem .5em;
  border: 1px solid white;
  border-radius: 6px;
  cursor: pointer;
  -webkit-user-select: none;
     -moz-user-select: none;
      -ms-user-select: none;
          user-select: none;
}

.pred-list__head label:hover {
  border: 1px solid #c2c2c2;
}

.pred-list__head label:active {
  background-color: #fcfcfc;
  -webkit-transform: scale(0.975);
          transform: scale(0.975);
}

.pred-list__head label .arrow {
  height: 24px;
  width: 24px;
  -webkit-transform: rotate(0deg);
          transform: rotate(0deg);
  -webkit-transition: -webkit-transform 0.5s ease 0s;
  transition: -webkit-transform 0.5s ease 0s;
  transition: transform 0.5s ease 0s;
  transition: transform 0.5s ease 0s, -webkit-transform 0.5s ease 0s;
}

.pred-list__head label .arrow svg {
  height: 24px;
  width: 24px;
}

/*
 der max-height Trick für accordeons ist out. Besser mit GRID:

    * https://www.youtube.com/watch?v=B_n4YONte5A (Kevin Powell)
    * https://keithjgrant.com/posts/2023/04/transitioning-to-height-auto/
*/
.pred-list__content {
  position: relative;
  z-index: 1;
  margin: 0px 1px 1px 1px;
  /* BUG? in FF, Border-Right sonst manchmal! unsichtbar */
  font-size: 0.8rem;
  border: 1px solid #d1d1d1;
  border-bottom-right-radius: 6px;
  border-bottom-left-radius: 6px;
  border-top: none;
  /* .pred-lis input:checked als trigger */
  display: -ms-grid;
  display: grid;
  -ms-grid-rows: 0fr;
      grid-template-rows: 0fr;
  opacity: 0;
  -webkit-transition: grid-template-rows 0.6s ease-out,
 opacity 0.6s;
  transition: grid-template-rows 0.6s ease-out,
 opacity 0.6s;
  transition: grid-template-rows 0.6s ease-out,
 opacity 0.6s,
 -ms-grid-rows 0.6s ease-out;
  /* .pred-list__content__inner */
}

.pred-list__content > div {
  overflow: hidden;
}

.pred-list__content__inner > div {
  padding: 1rem;
}

.pred-list__content .predicate {
  font-weight: bold;
}

.pred-list__content ul {
  list-style: none;
  margin: 0rem 0rem 1rem 0rem;
  padding-left: 1.2rem;
}

.pred-list__content li::marker {
  content: "";
}

.pred-list__content .examples {
  margin: 0;
}

