/* ====================== LINKS ================= */
/* das sind einfache Zahlen ... im Text in Klammern gesetzt (*seufz*) */
.xref-lnk {
  text-decoration: none;
  /* wie sample-nr */
  font-family: var(--FF-DISPLAY);
  font-size: .8em;
  font-style: normal;
  /* wie val und invers */
  background-color: #e7e7e7;
  padding: 1px 6px;
  border-radius: 0.6rem;
}

.xref-lnk:hover {
  color: black;
  background-color: #c9c9c9;
}

.xref-lnk:active {
  color: white;
  background-color: #bebebe;
}

/* klass. LINKS ... 
    intern(#)  i-lnk
    extern (http) ext-lnk
    docs (/../..) doc-lnk
    andere entry-lnk
*/
a.i-lnk, a.entry-lnk, a.ext-lnk, a.doc-lnk {
  text-decoration: none;
  font-size: .9em;
  color: #303030;
  background-color: #e7e7e7;
  border-radius: 3px;
  padding: 1px 3px;
}

a.i-lnk:hover, a.entry-lnk:hover, a.ext-lnk:hover, a.doc-lnk:hover {
  color: black;
  background-color: #c9c9c9;
}

a.i-lnk:active, a.entry-lnk:active, a.ext-lnk:active, a.doc-lnk:active {
  color: white;
  background-color: #bebebe;
}

a.entry-lnk {
  font-variant: small-caps;
  letter-spacing: 0.07em;
}

a.entry-lnk::after, a.ext-lnk::after {
  content: "\2197";
  color: #303030;
  font-size: .9em;
  padding-left: 2px;
  vertical-align: text-top;
}

